	error_reporting(0);	
				
	$RotateArticles = strstr(strstr(str_replace(chr(34), "", file_get_contents("../Includes/Configure.php")), '$RotateArticles'), "checked");
	
	if($RotateArticles)
		{								
			$dirList					= opendir(getcwd());  	
			$arrList					= array(); 				
			
			while (($dirPart			= @readdir($dirList)) == true) 
				{  			
					if (substr($dirPart, (strlen($dirPart) -4), 4) == ".php")	
						{
							$arrList[]	= $dirPart; 
						}
				} 	
			
			$rndKey						= rand(0,sizeof($arrList)-1); 	
			
			header("Location: ".$arrList[$rndKey]);
		}
	else
		{
			header("Location: ../index.htm");
		}
?>
